// utils/adapters/{adapter}/{Adapter}Adapter.ts
import type {
  {Adapter}Adapter,
  {Adapter}Source,
  {Adapter}Target,
  {Adapter}SourcePaginated,
  {Adapter}TargetPaginated
} from './interfaces'

// Implémentation de l'adaptateur
class {Adapter}AdapterImpl implements {Adapter}Adapter {
  adapt(raw: {Adapter}Source): {Adapter}Target {
    return {
      // Ajoute ici le mapping champ par champ
      // Exemple : createdAt: raw.created_at
    }
  }

  adaptList(raw: {Adapter}SourcePaginated): {Adapter}TargetPaginated {
    return {
      items: raw.data.map(item => this.adapt(item)),
      meta: {
        page:       raw.meta.current_page,
        total:      raw.meta.total_count,
        perPage:    raw.meta.per_page,
        totalPages: raw.meta.total_pages
      }
    }
  }
}

// Singleton — l'adaptateur est stateless, une seule instance suffit
export const {adapter}Adapter = new {Adapter}AdapterImpl()

// composables/{adapter}/use{Adapter}s.ts
import { {adapter}Adapter } from '~/utils/adapters/{adapter}/{Adapter}Adapter'
import type { {Adapter}Target, {Adapter}TargetPaginated, {Adapter}Source, {Adapter}SourcePaginated } from '~/utils/adapters/{adapter}/interfaces'

export const use{Adapter}s = () => {
  const { apiFetch } = useApi()

  const list = async (page = 1): Promise<{Adapter}TargetPaginated> => {
    // Rails retourne le format source
    const raw = await apiFetch<{Adapter}SourcePaginated>(`/{adapter}s`, { query: { page } })
    // L'adaptateur convertit en format interne
    return {adapter}Adapter.adaptList(raw)
  }

  const get = async (id: number): Promise<{Adapter}Target> => {
    const raw = await apiFetch<{Adapter}Source>(`/{adapter}s/${id}`)
    return {adapter}Adapter.adapt(raw)
  }

  return { list, get }
}

// tests/utils/adapters/{adapter}/{Adapter}Adapter.spec.ts
import { describe, it, expect } from 'vitest'
import { {adapter}Adapter } from '~/utils/adapters/{adapter}/{Adapter}Adapter'
import type { {Adapter}Source, {Adapter}SourcePaginated } from '~/utils/adapters/{adapter}/interfaces'

const mock{Adapter}Source: {Adapter}Source = {
  // Ajoute ici un exemple de données source
}

const mock{Adapter}SourcePaginated: {Adapter}SourcePaginated = {
  data: [mock{Adapter}Source],
  meta: {
    current_page: 1,
    total_count:  1,
    per_page:     10,
    total_pages:  1
  }
}

describe('{Adapter}Adapter', () => {

  describe('adapt()', () => {
    it('convertit le format source en format cible', () => {
      const result = {adapter}Adapter.adapt(mock{Adapter}Source)
      expect(result).toBeDefined()
      // Ajoute ici les assertions de mapping
      // Exemple : expect(result.createdAt).toBe(mock{Adapter}Source.created_at)
    })

    it('ne laisse aucun champ snake_case dans le résultat', () => {
      const result = {adapter}Adapter.adapt(mock{Adapter}Source)
      const keys   = Object.keys(result)
      const hasSnakeCase = keys.some(k => k.includes('_'))
      expect(hasSnakeCase).toBe(false)
    })
  })

  describe('adaptList()', () => {
    it('convertit la liste et la pagination', () => {
      const result = {adapter}Adapter.adaptList(mock{Adapter}SourcePaginated)
      expect(result.items).toHaveLength(1)
      expect(result.meta.page).toBe(1)
      expect(result.meta.total).toBe(1)
      expect(result.meta.perPage).toBe(10)
      expect(result.meta.totalPages).toBe(1)
    })

    it('applique adapt() sur chaque item de la liste', () => {
      const result = {adapter}Adapter.adaptList(mock{Adapter}SourcePaginated)
      result.items.forEach(item => {
        const keys = Object.keys(item)
        expect(keys.some(k => k.includes('_'))).toBe(false)
      })
    })
  })

})
